insert into public.permissions(code,description) values('settings.manage','Manage institution display and operational settings') on conflict(code) do nothing;
insert into public.role_permissions(role_id,institution_id,permission_code) select id,institution_id,'settings.manage' from public.roles where code in('super_admin','admin') on conflict do nothing;
create or replace function public.get_institution_settings()
returns jsonb language sql stable security definer set search_path=public,pg_temp as $$ select jsonb_build_object('branding',i.branding,'settings',coalesce(i.branding->'operational_settings','{}'::jsonb)) from public.institutions i where i.id=public.current_institution_id() and public.has_permission('settings.manage') $$;
create or replace function public.save_institution_settings(p_branding jsonb,p_settings jsonb)
returns void language plpgsql security definer set search_path=public,pg_temp as $$ begin if not public.has_permission('settings.manage') then raise exception 'permission denied'; end if; update public.institutions set branding=coalesce(p_branding,'{}'::jsonb)||jsonb_build_object('operational_settings',coalesce(p_settings,'{}'::jsonb)),updated_at=now() where id=public.current_institution_id(); insert into public.audit_events(institution_id,actor_profile_id,action,target_type,target_id,after_state) values(public.current_institution_id(),auth.uid(),'INSTITUTION_SETTINGS_UPDATED','institution',public.current_institution_id(),jsonb_build_object('safe_settings_updated',true)); end $$;
revoke all on function public.get_institution_settings(),public.save_institution_settings(jsonb,jsonb) from public;grant execute on function public.get_institution_settings(),public.save_institution_settings(jsonb,jsonb) to authenticated;
